head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusMode]<br/>GridView 컴포넌트의 Body 또는 Footer 영역 선택 시 포커스 되는 형식을 설정합니다.",
    "validation" : [
        "focusMode 가 'none' 이 아닐때 syncRowPositionOption 이 'style','focus' 이면 DataList 의 RowPosition 변경 시 해당 Row 로 포커스가 자동 이동됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_focusMode / con_syncRowPositionOption 두 옵션을 con 으로 반영하여 GridView 동적 생성
//  - selectedCellColor(red) / selectedRowColor(blue) 를 서로 다른 색으로 설정하여
//    포커스가 이동한 Row/Cell 을 배경색으로 구분 관찰 가능하게 함
//  - 여러 Row 가 보이도록 dataList 바인딩
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 옵션 수집 (정적 xf:item + getValue, 빈값은 createCList 가 자동 제외)
    let cFocusMode = con_focusMode.getValue();
    let cSyncRowPositionOption = con_syncRowPositionOption.getValue();

    let properties = {
        focusMode             : cFocusMode,
        syncRowPositionOption : cSyncRowPositionOption,
        selectedCellColor     : "red",
        selectedRowColor      : "blue"
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    let eList = $c.gcm.createEList(["oncellclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFocus = (cFocusMode === '') ? '미설정' : cFocusMode;
    let lblSync = (cSyncRowPositionOption === '') ? '미설정' : cSyncRowPositionOption;
    $c.gcm.createLabel('label="focusMode=' + lblFocus + ' / syncRowPositionOption=' + lblSync + ' 로 GridView 생성 (selectedCellColor=red, selectedRowColor=blue). RowPosition 변경 버튼으로 자동 포커스 이동 여부 확인"', '', 'label1');

    // dataList 생성 (여러 Row 바인딩)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (4컬럼 Body 그리드)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="focusMode 자동 포커스 이동 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 초기 RowPosition 정렬 + 기본 포커스 셀 설정
    //  - focusMode != 'none' 이면 기본 포커스 셀(0,0)을 설정해야 이후 RowPosition 변경 시 포커스가 이동됨
    //    (특히 cell 모드는 사전 포커스 셀이 없으면 자동 이동이 동작하지 않음)
    dlt_bind.setRowPosition(0);
    let effMode = (cFocusMode === '') ? 'cell' : cFocusMode;
    if (effMode !== 'none') {
        target1.setFocusedCell(0, 0);
    }
}



// "RowPosition 변경" 버튼
//  - DataList 의 RowPosition 을 par_rowPosition 으로 선택한 값으로 변경 (setRowPosition)
//  - @spec : focusMode != 'none' + syncRowPositionOption = 'style'/'focus' 이면
//    RowPosition 변경 시 해당 Row 로 포커스가 자동 이동 → getFocusedRowIndex 가 변경값과 일치
//  - focusMode='none' 이거나 syncRowPositionOption 미설정이면 자동 이동하지 않음
//  - 변경 후 RowPosition 과 실제 포커스 Row 인덱스를 비교 출력
scwin.btn_setRowPosition_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let newPos = parseInt(par_rowPosition.getValue(), 10);
    let mode = target1.options.focusMode;
    let sync = target1.options.syncRowPositionOption;

    // 변경 전 포커스 Row 인덱스
    let beforeRow = target1.getFocusedRowIndex();

    // DataList RowPosition 변경 → notifyRowPositionChanged 트리거
    dlt_bind.setRowPosition(newPos);

    // 변경 후 포커스 Row 인덱스 (자동 이동 시 newPos 와 일치)
    let afterRow = target1.getFocusedRowIndex();
    let moved = (afterRow === newPos);

    bottom.setReturnValue("[옵션] focusMode=" + (mode === '' ? '미설정' : mode) + " / syncRowPositionOption=" + (sync === '' ? '미설정' : sync));
    bottom.setReturnValue("[RowPosition 변경] " + newPos + " 으로 setRowPosition 호출");
    bottom.setReturnValue("[포커스 Row 인덱스] 변경 전 " + beforeRow + " → 변경 후 " + afterRow);
    bottom.setReturnValue("[자동 포커스 이동 여부] RowPosition(" + newPos + ") == 포커스 Row(" + afterRow + ") : " + moved);
}



// oncellclick : 사용자가 셀을 클릭하면 발생 (focusMode='cell' 환경에서 자동 이동 전 사전 포커스 셀 마련용으로도 사용)
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    bottom.setReturnValue("=====target1_oncellclick=====");
    bottom.setReturnValue("rowIndex : " + rowIndex + " / columnIndex : " + columnIndex + " / columnId : " + columnId);
}
